const express = require('express');
const { InfluxDB } = require('@influxdata/influxdb-client');

const app = express();
app.use(express.json());

const client = new InfluxDB({ url: process.env.INFLUX_URL, token: process.env.INFLUX_TOKEN });
const queryApi = client.getQueryApi(process.env.INFLUX_ORG);

app.post('/api/telemetry/flux-query', async (req, res) => {
  const { factoryId, timeRange } = req.body;

  // Ensure the user has permission to access the requested factory
  if (!req.user.assignedFactories.includes(factoryId)) {
    return res.status(403).json({ error: 'Access to specified factory telemetry is forbidden' });
  }

  // Safe sanitized parameter binding in Flux
  const fluxQuery = `
    from(bucket: "factory_telemetry")
      |> range(start: ${timeRange || '-1h'})
      |> filter(fn: (r) => r._measurement == "vibration" or r._measurement == "temperature")
      |> filter(fn: (r) => r.factory_id == "${factoryId}")
  `;

  const results = [];
  try {
    await queryApi.queryRows(fluxQuery, {
      next(row, tableMeta) {
        results.push(tableMeta.toObject(row));
      },
      error(error) {
        res.status(500).json({ error: error.message });
      },
      complete() {
        res.json({ factoryId, data: results });
      }
    });
  } catch (err) {
    res.status(500).json({ error: 'Query execution error' });
  }
});

module.exports = app;
